    # The large L-shaped object is a color stencil: its two arms indicate
    # the color to apply to the other objects lying beyond its endpoints.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
