                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    for color, cells in comps:
        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
        # L marker has long perpendicular arms, often with a one-cell gap.
        if len(cells) < 6 or r1-r0 < 2 or c1-c0 < 2:
            continue
        horiz = sum(1 for r, c in cells if r == r0)
        vert = sum(1 for r, c in cells if c == c0 or c == c1)
        if horiz < 3 or vert < 3:
            continue

        # Recolor objects touching the outside of either arm.
        for rr, cc in cells:
            for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                y, x = rr+dy, cc+dx
                if 0 <= y < h and 0 <= x < w and grid[y][x] != bg:
                    target = grid[y][x]
                    if target != color:
                        for tc, part in comps:
                            if tc == target and (y,x) in part:
                                for py, px in part:
                                    out[py][px] = color
    return out
