        cs = [c for r,c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        # Recognize an L-shaped marker with long horizontal and vertical arms.
        corners = []
        for r in (r0, r1):
            for c in (c0, c1):
                if (r,c) in cells:
                    hr = sum((r,x) in cells for x in range(c0,c1+1))
                    vr = sum((y,c) in cells for y in range(r0,r1+1))
                    if hr >= 3 and vr >= 3:
                        corners.append((r,c,hr,vr))
        if not corners:
            continue
        cr, cc, _, _ = max(corners, key=lambda q: q[2]+q[3])
        # The target lies diagonally opposite the directions of the L's arms.
        dr = 1 if cr == r0 else -1
        dc = 1 if cc == c0 else -1
        choices = []
        for other_color, part in comps:
            if other_color == color:
                continue
            cy = sum(y for y,x in part)/len(part)
            cx = sum(x for y,x in part)/len(part)
            if (cy-cr)*dr < 0 and (cx-cc)*dc < 0:
                dist = abs(cy-cr)+abs(cx-cc)
                choices.append((dist, other_color, part))
        if choices:
            _, _, target = min(choices, key=lambda z:z[0])
            for y,x in target:
                out[y][x] = color
    return out
